    #[tokio::test]
    async fn test_tmp_dynamic_with_workspaces_outside_workspace() {
        use tokio::sync::RwLock;

        use crate::{ManagerMode, WorkspaceWorker};

        let init_options = InitializeRequestOptions { pull_mode: true, ..Default::default() };
        let mut server = TestServer::new_initialized(
            |client| {
                let builder = Arc::new(FakeToolBuilder::new(DiagnosticMode::Pull));
                let dynamic_worker = WorkspaceWorker::new(
                    "file:///".parse().unwrap(),
                    builder.clone(),
                    DiagnosticMode::Pull,
                );
                let manager = WorkerManager::new_with_mode(
                    builder,
                    ManagerMode::DynamicWithWorkspaces(Box::new(RwLock::new(dynamic_worker))),
                );
                Backend::new(client, server_info(), manager)
            },
            initialize_request(init_options),
        )
        .await;

        // A file OUTSIDE the workspace root (WORKSPACE = file:///path/to/workspace)
        let outside = "file:///some/other/place/diagnostics.config";
        server.send_request(did_open(outside, "content")).await;
        server.send_request(diagnostic(3, outside)).await;

        let resp = server.recv_response().await;
        assert!(resp.is_ok());
        let report: serde_json::Value =
            serde_json::from_value(resp.result().unwrap().clone()).unwrap();
        assert_eq!(report["kind"], "full");
        assert_eq!(report["items"].as_array().unwrap().len(), 1);

        server.shutdown(4).await;
    }

